So here's the entity code:
```ts
@Entity('MON_CONTROL_PLACE', {
  orderBy: {
    name: 'ASC',
    id: 'DESC',
  },
} as any)
export class ControlPlace {
  @PrimaryGeneratedColumn({
    // name: 'MON_CONTROL_PLACE_ID',
  })
  id: number

  @Column({
    nullable: false,
    unique: true,
  })
  name: string

  // Relations
  @OneToMany(
    (type) => RouteLine,
    (routeLine) => routeLine.controlPlace,
  )
  routeLines: Promise<RouteLine[]>

  @CreateDateColumn()
  createdAt: Date

  @UpdateDateColumn()
  updatedAt: Date

  @VersionColumn()
  version: number
}
```
Here's the relation code:
```ts
@Entity('MON_ROUTE_LINE', {
  orderBy: {
    id: 'DESC',
  },
} as any)
export class RouteLine {
  @PrimaryGeneratedColumn({
    name: 'MON_ROUTE_LINE_ID',
  })
  id: number

  @Column('real', {
    default: 0,
  })
  kms: number

  @Column('time without time zone', {
    nullable: false,
  })
  horas: Date

  // Relations
  @ManyToOne(
    (type) => Route,
    (route) => route.routeLines,
    { nullable: false },
  )
  @JoinColumn({
    // name: 'MON_ROUTE_ID',
  })
  route: Promise<Route>

  @ManyToOne(
    (type) => ControlPlace,
    (controlPlace) => controlPlace.routeLines,
    { nullable: false },
  )
  @JoinColumn({
    // name: 'MON_CONTROL_PLACE_ID',
  })
  controlPlace: Promise<ControlPlace>

  @CreateDateColumn()
  createdAt: Date

  @UpdateDateColumn()
  updatedAt: Date

  @VersionColumn()
  version: number
}
```
